require 'uri'
require 'cgi'
require File.expand_path(File.join(File.dirname(__FILE__), "..", "support", "paths"))
require File.expand_path(File.join(File.dirname(__FILE__), "..", "support", "selectors"))

module WithinHelpers
  def with_scope(locator)
    locator ? within(*selector_for(locator)) { yield } : yield
  end
end
World(WithinHelpers)

Given /^(?:|I )am on (.+)$/ do |page_name|
  visit path_to(page_name)
end

When /^(?:|I )go to (.+)$/ do |page_name|
  path = path_to(page_name)
  duped_path = path.dup
  visit duped_path
end

When /^(?:|I )press "([^"]*)"$/ do |button|
  @last_alert_text = nil
  click_button(button)
  # Accept any JavaScript alert the button raised, remembering its text so a
  # later step can assert on it (see "I should see an alert with").
  if page.driver.browser.respond_to?(:switch_to)
    begin
      alert = page.driver.browser.switch_to.alert
      @last_alert_text = alert.text
      alert.accept
    rescue Selenium::WebDriver::Error::NoSuchAlertError
      # No alert, continue normally
    end
  end
end

When /^(?:|I )follow "([^"]*)"$/ do |link|
  # Handle ambiguous Profile links by preferring the submenu Profile link for editing
  if link == "Profile"
    # Look for the Profile link in the submenu context
    within('#profile') do
      click_link(link)
    end
  else
    click_link(link)
  end
end

When /^(?:|I )click inside "([^"]*)"$/ do |selector|
  find(:css, selector).click
end

When /^(?:|I )click inside the first "([^"]*)"$/ do |selector|
  first(:css, selector).click
end

When /^(?:|I )fill in "([^"]*)" with "([^"]*)"$/ do |field, value|
  # Wait for the field to be present
  expect(page).to have_field(field, wait: 10)
  
  # Clear any existing value first if it's a filter field
  if field == "filter"
    # The filter field has a default value, need to clear it
    filter_field = find_field(field)
    filter_field.click
    filter_field.set('')
  end
  
  fill_in(field, :with => value)
  
  # Trigger keyup event for filter fields
  if field == "filter"
    find_field(field).native.send_keys(:return)
  end
end

When /^(?:|I )fill in the textarea with "([^"]*)"$/ do |value|
  find(:xpath, "//form/textarea").set value
end

# Use this to fill in an entire form with data from a table. Example:
#
#   When I fill in the following:
#     | Account Number | 5002       |
#     | Expiry date    | 2009-11-01 |
#     | Note           | Nice guy   |
#     | Wants Email?   |            |
#
# TODO: Add support for checkbox, select or option
# based on naming conventions.
#
When /^(?:|I )fill in the following:$/ do |fields|
  fields.rows_hash.each do |name, value|
    step %{I fill in "#{name}" with "#{value}"}
  end
end

Then /^(?:|I )should see "([^"]*)"$/ do |text|
  if page.respond_to? :should
    page.should have_content(text)
  else
    assert page.has_content?(text)
  end
end

Then /^(?:|I )should see \/([^\/]*)\/$/ do |regexp|
  regexp = Regexp.new(regexp)

  if page.respond_to? :should
    page.should have_xpath('//*', :text => regexp)
  else
    assert page.has_xpath?('//*', :text => regexp)
  end
end

Then /^(?:|I )should not see "([^"]*)"$/ do |text|
  if page.respond_to? :should
    page.should have_no_content(text)
  else
    assert page.has_no_content?(text)
  end
end

Then /^the "([^"]*)" field(?: within (.*))? should contain "([^"]*)"$/ do |field, parent, value|
  with_scope(parent) do
    field = find_field(field)
    field_value = (field.tag_name == 'textarea') ? field.text : field.value
    if field_value.respond_to? :should
      field_value.should =~ /#{value}/
    else
      assert_match(/#{value}/, field_value)
    end
  end
end

Then /^(?:|I )should be on ([^"]+(?:\s[^"]+)*)$/ do |page_name|
  current_path = URI.parse(current_url).path
  if current_path.respond_to? :should
    current_path.should == path_to(page_name)
  else
    assert_equal path_to(page_name), current_path
  end
end

Given(/^I wait (\d+) second(?:s)?$/) do |seconds|
  sleep seconds.to_i
end

When /^I visit the memverse page with id <memverse_id>$/ do
  visit "/memory_verse/#{@memverse_id}"
end

Then /^I should see the verse text$/ do
  # Check if we're on the sign-in page (user was logged out due to database truncation)
  if page.has_content?("YOU NEED TO SIGN IN OR SIGN UP BEFORE CONTINUING.")
    # User was logged out, sign in again
    if @current_user_email
      # Ensure the user exists and is confirmed
      user = User.find_by_email(@current_user_email)
      if user.nil?
        user = User.create!(
          name: "Old Dog",
          email: @current_user_email,
          password: "please",
          password_confirmation: "please"
        )
        user.confirm
        user.save!
      end
      # Go to sign in page
      visit "/users/sign_in"
      # Print CSRF token meta tag for debugging
      if page.has_selector?('meta[name="csrf-token"]', visible: false)
        puts "CSRF token: #{page.find('meta[name="csrf-token"]', visible: false)[:content]}"
      else
        puts "No CSRF token meta tag found!"
      end
      # Use within form for robustness
      within('form') do
        fill_in "user[email]", with: @current_user_email
        fill_in "user[password]", with: "please"
        find("#signinbutton", visible: :all).click
      end
      sleep 1 # Wait for the session to be established
      # Fallback: try click_button by id if still on sign-in page
      if page.has_content?("YOU NEED TO SIGN IN OR SIGN UP BEFORE CONTINUING.")
        begin
          click_button("signinbutton")
          sleep 1
        rescue => e
          puts "click_button fallback failed: #{e}"
        end
      end
      # If still on sign-in page, print the page HTML for debugging
      if page.has_content?("YOU NEED TO SIGN IN OR SIGN UP BEFORE CONTINUING.")
        puts "=== DEBUG: Still on sign-in page after sign-in attempt ==="
        puts page.html
      end
      # Visit the memverse page again
      visit "/memory_verse/#{@memverse_id}"
    end
  end
  
  verse = Memverse.find(@memverse_id).verse
  expect(page).to have_content(verse.text)
end
